import type { ReservationStatus, Role } from '@reservas/shared';

/** Entidades puras de dominio: sin tipos de Prisma/Express/ws. */
export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
}

export interface Room {
  id: string;
  name: string;
  capacity: number;
  equipment: string;
  isActive: boolean;
}

export interface Reservation {
  id: string;
  roomId: string;
  userId: string;
  title: string;
  startTime: Date;
  endTime: Date;
  attendeesCount: number;
  status: ReservationStatus;
  movedByHr: boolean;
}
import type { WsEvent } from '@reservas/shared';
import type { Reservation, Room, User } from '../entities';

export interface UserRepository {
  findById(id: string): Promise<User | null>;
}

export interface RoomRepository {
  findById(id: string): Promise<Room | null>;
  save(room: Room): Promise<void>;
}

export interface ReservationRepository {
  findById(id: string): Promise<Reservation | null>;
  /** Reservas CONFIRMED de la sala que cumplen `newStart < existingEnd && newEnd > existingStart`. */
  findOverlapping(roomId: string, start: Date, end: Date, excludeId?: string): Promise<Reservation[]>;
  /**
   * Inserta o actualiza. El adaptador DEBE garantizar atomicidad y lanzar `ConflictError`
   * si existe solape CONFIRMED (segunda barrera tras la validación del caso de uso).
   */
  save(reservation: Reservation): Promise<void>;
}

export interface NotificationPort {
  notifyDataInvalidated(entity: WsEvent['entity']): Promise<void> | void;
}

/** Dependencias transversales inyectables para tests deterministas. */
export interface Clock {
  now(): Date;
}
export interface IdGenerator {
  next(): string;
}
services:
  db:
    image: postgres:16-alpine
    environment:
      POSTGRES_USER: reservas
      POSTGRES_PASSWORD: reservas
      POSTGRES_DB: reservas
    volumes:
      - postgres_data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U reservas -d reservas"]
      interval: 5s
      timeout: 5s
      retries: 10

  api:
    build:
      context: .
      dockerfile: apps/api/Dockerfile
    environment:
      PORT: 3000
      DATABASE_URL: postgresql://reservas:reservas@db:5432/reservas
    ports:
      - "3000:3000"
    depends_on:
      db:
        condition: service_healthy

  web:
    build:
      context: .
      dockerfile: apps/web/Dockerfile
    environment:
      VITE_API_URL: http://localhost:3000
      VITE_WS_URL: ws://localhost:3000/ws
    ports:
      - "5173:5173"
    depends_on:
      - api

volumes:
  postgres_data:
import { defineConfig } from 'vitest/config';
export default defineConfig({ test: { environment: 'node', include: ['src/**/*.spec.ts'] } });
# T-04 · Casos de Uso de Dominio (`apps/api/src/application/use-cases`)

**Fecha:** 2026-11-14 22:40 CST — **Estado:** completada

## Objetivo
Implementar los casos de uso `CreateReservation`, `MoveReservation`, `CancelReservation` y `ManageRoom` como lógica pura que depende solo de puertos del dominio, validando las invariantes de la spec §4 (choques, duración 30 min–4 h, anticipación ≤ 14 días, horario L–V 07:00–20:00, aforo, `movedByHr`) y notificando vía `NotificationPort`.

## Ciclo TDD
- **Red:** escribí los 4 `.spec.ts` (57 casos nuevos) más fakes in-memory y puertos; las 4 suites fallaron por módulos inexistentes.
- **Green:** implementé `NotFoundError`, `ReservationRules` y los 4 casos de uso. Dos fallos iniciales fueron defectos de test/fake (hora local ya pasada respecto a `NOW`; el fake reutilizaba `findOverlapping` en `save`, anulando la barrera atómica al stubearlo); corregidos sin tocar el código de producción. 77/77 en verde.
- **Refactor:** reglas de slot/aforo extraídas a `ReservationRules` (DRY entre Create y Move); `movedByHr` y permisos delegados en `AuthorizationPolicy` (T-03).

## Archivos tocados
- `apps/api/src/domain/entities/index.ts` (User, Room, Reservation puras)
- `apps/api/src/domain/ports/index.ts` (UserRepository, RoomRepository, ReservationRepository, NotificationPort, Clock, IdGenerator)
- `apps/api/src/domain/errors/index.ts` (+ `NotFoundError`)
- `apps/api/src/domain/policies/ReservationRules.ts`
- `apps/api/src/application/use-cases/{CreateReservation,MoveReservation,CancelReservation,ManageRoom}.ts` y sus `.spec.ts`
- `apps/api/src/application/use-cases/__fakes__/inMemory.ts` (repos in-memory, spy, reloj fijo)

## Decisiones
- **`NotFoundError` (code `NOT_FOUND`)** añadido: el backlog de T-03 listaba 4 errores, pero T-06 exige mapear 404 y los casos de uso necesitan señalar sala/reserva inexistente.
- **Doble barrera de solapes:** el caso de uso pre-valida con `findOverlapping`; `ReservationRepository.save` debe re-validar atómicamente y lanzar `ConflictError` (el adaptador Prisma `Serializable` lo hará en T-05). Un test simula la carrera.
- **Zona horaria operativa:** el horario 07:00–20:00 se evalúa en UTC-6 (`DEFAULT_UTC_OFFSET_MINUTES`, coherente con CST), inyectable en `ReservationRules`; el contrato usa ISO UTC. Supuesto no indicado en la spec.
- **Anticipación:** `start >= now` y `start <= now + 14 días` (exactamente 14 días se acepta). Bordes de duración/horario inclusivos; reservas contiguas permitidas.
- **Move:** el slot se revalida solo si cambian `startTime`/`endTime` (permite a HR editar título de una reunión en curso); sala y aforo se validan siempre sobre el estado resultante; `movedByHr` es sticky (`actual || HR sobre ajena`). Reservas `CANCELLED` no se pueden mover/cancelar (`ValidationError`, 422).
- `Clock` e `IdGenerator` inyectados para tests deterministas.

## Evidencia
- `npm test` (monorepo): shared 30/30, api 77/77, web 1/1.
- `npx tsc -p apps/api/tsconfig.json`: sin errores.
- `grep` de `prisma|express|ws` en `src/domain` y `src/application`: sin coincidencias.

